@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@400;500;600;700;800;900&family=Barlow:wght@400;500;600;700&display=swap');
:root{--lime:#c5e17c;--paper:#e9e9df;--muted:#9a9d94;--line:rgba(235,240,222,.18)}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#101513;color:var(--paper);font-family:Barlow,Arial,sans-serif}button{font:inherit;color:inherit;cursor:pointer}#gameShell{position:relative;width:100vw;height:100dvh;overflow:hidden;background:#151a18;isolation:isolate}#scene{position:absolute;inset:0;width:100%;height:100%;display:block}.screen{position:absolute;inset:0;z-index:5;display:flex;align-items:center;padding:clamp(28px,8vw,130px);background:linear-gradient(90deg,rgba(8,12,11,.88) 0%,rgba(8,12,11,.56) 42%,rgba(8,12,11,.02) 100%),linear-gradient(0deg,rgba(9,12,11,.55),transparent 40%)}.hidden{display:none!important}.title-copy{width:min(580px,100%);margin-top:5vh}.eyebrow{font-size:10px;font-weight:700;letter-spacing:2.6px;color:#c7c9bd;display:flex;align-items:center;gap:11px}.eyebrow i,.rec{width:7px;height:7px;border-radius:50%;background:#c9e283;box-shadow:0 0 12px #c9e283}.title-copy h1{font-family:'Barlow Condensed',Impact,sans-serif;font-size:clamp(72px,12.5vw,166px);line-height:.77;letter-spacing:-.04em;margin:28px 0 0;font-weight:800;text-shadow:0 4px 34px #0008}.title-copy h1 span{color:var(--lime)}.subtitle{font-family:'Barlow Condensed',sans-serif;font-size:22px;letter-spacing:8px;font-weight:600;margin:17px 0 29px;color:#d0d2c8}.story{font-size:14px;line-height:1.75;color:#c3c4bc;margin:0 0 32px}.title-actions{display:flex;align-items:center;gap:12px}.primary,.secondary{min-height:48px;padding:0 23px;border:1px solid var(--lime);font-family:'Barlow Condensed',sans-serif;font-size:15px;letter-spacing:1.3px;font-weight:700;transition:.2s}.primary{background:var(--lime);color:#182017}.primary span{font-size:20px;margin-left:20px}.primary:hover{background:#e2f5ab;transform:translateY(-2px);box-shadow:0 7px 25px #c5e17c33}.secondary{background:#1015128c;border-color:#aaa99d;color:#e5e5dc}.secondary:hover{border-color:var(--li