eat(3,1fr);gap:10px;margin-bottom:21px}.stat-list span{position:relative;display:grid;grid-template-columns:1fr auto;gap:6px}.stat-list b{font:600 11px Barlow;color:#ddd}.stat-list i{height:3px;background:#42473f;grid-column:span 2}.stat-list em{display:block;height:100%;background:var(--lime)}.backBtn{position:absolute;top:36px;left:clamp(28px,8vw,130px);background:transparent;border:0;font:600 12px Barlow Condensed;letter-spacing:1.5px}.hud{pointer-events:none}.topHud{position:absolute;z-index:2;top:30px;left:38px;right:38px;display:flex;align-items:flex-start;justify-content:space-between;text-shadow:0 2px 8px #000}.missionTag{display:flex;gap:11px;align-items:center}.missionTag .rec{width:6px;height:6px;background:#e45c4d;box-shadow:0 0 10px #e45c4d}.missionTag div{display:grid;gap:4px}.missionTag small,.objective small{font-size:9px;letter-spacing:1.8px;color:#c3c6b8}.missionTag strong{font:700 15px 'Barlow Condensed';letter-spacing:.8px}.compass{position:absolute;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:21px;color:#adb1a6;font:600 11px 'Barlow Condensed';padding:7px 15px;background:#080b0980;border-bottom:1px solid #d6dab64f}.compass b{color:#f0f0e7}.compass i{position:absolute;left:50%;top:22px;color:var(--lime);font-size:15px;font-style:normal}.squadTag{font-size:10px;letter-spacing:1.2px;display:flex;gap:9px;align-items:center;background:#10151199;padding:8px 11px;border:1px solid #ffffff24}.squad-dot{width:6px;height:6px;background:var(--lime);border-radius:50%}.squadTag b{color:var(--lime);font-size:14px}.objective{position:absolute;left:38px;top:108px;display:flex;align-items:center;gap:12px;text-shadow:0 2px 8px #000}.objMark{font-size:24px;color:var(--lime)}.objective span:last-child{display:grid;gap:3px}.objective b{font:600 13px 'Barlow Condensed';letter-spacing:1px}.crosshair{position:absolute;left:50%;top:50%;width:24px;height:24px;transform:translate(-50%,-50%);transition:transform .12s}.crosshair i{position:absolute;background:#e8eddfd9;box-shadow:0 1px 3px #000;width:1px;height:6px}.crosshair i:nth-child(1){top:0;left:11px}.crosshair i:nth-child(2){bottom:0;left:11px}.crosshair i:nth-child(3){left:0;top:11px;width:6px;height:1px}.crosshair i:nth-child(4){right:0;top:11px;width:6px;height:1px}.crosshair b{position:absolute;width:2px;height:2px;background:#e8eddf;left:11px;top:11px}.hitmarker{position:absolute;display:none;left:50%;top:50%;transform:translate(-50%,-50%);font:300 31px Arial;color:white;text-shadow:0 0 5px #000}.hitmarker.show{display:block}.weaponHud{position:absolute;right:40px;bottom:35px;display:flex;align-items:flex-end;gap:17px;text-shadow:0 2px 6px #000}.ammo{display:flex;align-items:baseline;gap:6px}.ammo strong{font:600 49px/.8 'Barlow Condensed'}.ammo span{font:500 17px 'Barlow Condensed';color:#ddd}.ammo span b{font-weight:500;color:#aaa}.weaponHudMeta{display:grid;gap:5px;padding-bottom:1px}.weaponHudMeta b{font:700 14px 'Barlow Condensed';letter-spacing:.7px}.weaponHudMeta small{font-size:8px;letter-spacing:1.1px;color:#bbb}.weaponHudMeta small span{color:var(--lime)}.grenade{margin:0 8px 6px 12px;color:#d4dfc3}.grenade b{font:12px Barlow;color:white}.healthHud{position:absolute;bottom:39px;left:38px;display:flex;align-items:center;gap:10px;text-shadow:0 2px 6px #000}.healthIcon{width:29px;height:29px;display:grid;place-items:center;border:1px solid #b5c77d;color:var(--lime);font-size:19px}.healthHud div:nth-child(2){width:115px;display:grid;gap:5px}.healthHud div:nth-child(2) b{font:600 9px 'Barlow Condensed';letter-spacing:1.3px}.healthHud i{height:3px;background:#50554a}.healthHud i em{display:block;width:100%;height:100%;background:var(--lime);transition:width .2s}.healthHud>strong{font:600 18px 'Barlow Condensed'}.damageFlash{position:absolute;inset:0;background:radial-gradient(ellipse,transparent 35%,rgba(175,26,18,.62));opacity:0;transition:opacity .15s}.damageFlash.active{opacity:1}.toast{position:absolute;top:27%;left:50%;transform:translateX(-50%);font:700 13px 'Barlow Condensed';letter-spacing:2px;color:var(--lime);text-shadow:0 2px 8px #000;opacity:0;transition:opacity .3s}.toast.show{opacity:1}.interaction{position:absolute;bottom:19%;left:50%;transform:translateX(-50%);font:10px 'Barlow Condensed';letter-spacing:1.5px;color:#eee}.screen#pauseScreen,.screen#endScreen{justify-content:center;align-items:center;background:#080c0be0;backdrop-filter:blur(8px)}.pauseCard{text-align:center;width:min(410px,90vw);padding:42px;border:1px solid var(--line);background:#121714e8}.pauseCard .eyebrow{justify-content:center}.pauseCard h2{font-size:52px;margin:18px 0 26px}.pauseCard button{width:100%;margin:5px 0}.pauseCard>p{font-size:9px;line-height:1.9;letter-spacing:1px;color:#91958c;margin-top:24px}.resultStats{display:flex;justify-content:space-between;border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:14px 0;margin:20px 0}.resultStats span{display:grid;gap:7px}.resultStats b{font:600 20px 'Barlow Condensed';color:#e9e9df}.screen#armoryScreen{background:linear-gradient(90deg,#101513a8,#101513d9)}#mobileControls{display:none}.screen:before{content:'';position:absolute;inset:12px;border:1px solid #ffffff0a;pointer-events:none}.screen>*{position:relative}.title-copy,.armory-panel{z-index:1}
@media(max-width:700px){.screen{padding:28px 25px}.title-copy{margin-top:0}.title-copy h1{font-size:clamp(78px,19vw,125px);margin-top:26px}.subtitle{font-size:17px;letter-spacing:6px}.story{font-size:12px}.title-meta{left:25px;right:25px;font-size:7px;letter-spacing:1px}.title-meta span:last-child{display:none}.title-actions{flex-wrap:wrap}.primary,.secondary{min-height:45px;padding:0 16px}.armory-panel{padding:25px 22px}.backBtn{left:25px;top:22px}.topHud{top:16px;left:15px;right:15px}.missionTag strong{font-size:12px}.missionTag small{font-size:7px}.compass{top:54px}.squadTag{font-size:8px}.objective{left:15px;top:92px}.weaponHud{right:18px;bottom:25px;gap:9px}.ammo strong{font-size:43px}.weaponHudMeta b{font-size:12px}.weaponHudMeta small{font-size:7px}.grenade{display:none}.healthHud{left:16px;bottom:28px}.healthHud div:nth-child(2){width:75px}.pauseCard{padding:30px 24px}#mobileControls{display:block;position:absolute;z-index:3;inset:0;pointer-events:none}.movePad{position:absolute;left:18px;bottom:110px;pointer-events:auto}.movePad button,.touchActions button{background:#1015128c;border:1px solid #ffffff55;color:white;border-radius:50%;width:40px;height:40px;font-size:15px;touch-action:none}.movePad>button{margin:0 0 4px 42px}.movePad div{display:flex;gap:4px}.touchActions{position:absolute;right:14px;bottom:109px;display:grid;grid-template-columns:45px 45px;gap:7px;pointer-events:auto}.touchActions button{width:45px;height:45px;font-size:9px;font-weight:bold}.touchActions #touchFire{background:#9e493d99}.touchActions #touchAim{background:#656d5399}#startHint{position:absolute;z-index:4;bottom:22%;left:50%;transform:translateX(-50%);font-size:8px;letter-spacing:1px;text-align:center;display:grid;gap:7px;color:#ddd;text-shadow:0 1px 5px #000;white-space:nowrap}#startHint b{color:#bfcf86}}

(() => {
'use strict';
const canvas=document.getElementById('scene'),ctx=canvas.getContext('2d');
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const screens={title:$('#titleScreen'),armory:$('#armoryScreen'),pause:$('#pauseScreen'),end:$('#endScreen')};
const skins=[{name:'ESPECTRO',color:'#55604b',accent:'#bbc88a'},{name:'DESIERTO',color:'#a7855e',accent:'#e3c18b'},{name:'NOCHE',color:'#30383b',accent:'#80a9aa'},{name:'ÓXIDO',color:'#71493c',accent:'#dc9b70'},{name:'INVIERNO',color:'#8b9290',accent:'#e2e8de'}];
let skinIndex=0,mode='menu',last=0,elapsed=0,keys={},mouseLocked=false,aiming=false,sprinting=false,reloading=false,inspecting=false,inspectAt=0,shots=0,hits=0,kills=0,ammo=30,reserve=120,health=100,shake=0,recoil=0,toastTimer=0,damageTimer=0,walkBob=0,headBob=0,hitTimer=0,grenades=2;
const player={x:3.5,y:14.5,angle:-Math.PI/2,pitch:0,speed:0};
const map=[
'####################',
'#........#.........#',
'#........#.........#',
'#..##....#....##...#',
'#..##.........##...#',
'#..............#...#',
'###.####.####..#...#',
'#...#..#....#..#...#',
'#...#..#....#......#',
'#......#....####.###',
'#.##...#...........#',
'#.##.......##......#',
'#...........#......#',
'#....###....#...##.#',
'#....#......#...##.#',
'#....#.............#',
'#........#....#....#',
'#........#....#....#',
'#..................#',
'####################'];
const enemies=[];
const spawnEnemies=()=>{enemies.length=0;[[8.5,3.8],[15.4,5.3],[5.3,8.4],[13.2,11.3],[9.2,16.3],[16.4,14.4]].forEach((p,i)=>enemies.push({x:p[0],y:p[1],alive:true,hp:100,alert:false,fireAt:2+i*.9,phase:Math.random()*6,hit:0,walk:0}));};
spawnEnemies();
function resize(){const d=Math.min(devicePixelRatio||1,1.6);canvas.width=Math.floor(innerWidth*d);canvas.height=Math.floor(innerHeight*d);ctx.setTransform(d,0,0,d,0,0)}addEventListener('resize',resize);resize();
const W=()=>innerWidth,H=()=>innerHeight;
function wall(x,y){const ix=Math.floor(x),iy=Math.floor(y);return !map[iy]||map[iy][ix]==='#'}
function norm(a){while(a>Math.PI)a-=Math.PI*2;while(a< -Math.PI)a+=Math.PI*2;return a}
function showToast(t){const el=$('#toast');el.textContent=t;el.classList.add('show');toastTimer=1.6}
function setMode(m){mode=m;Object.values(screens).forEach(s=>s.classList.add('hidden'));$('#hud').classList.toggle('hidden',m!=='playing');if(m==='menu')screens.title.classList.remove('hidden');if(m==='armory')screens.armory.classList.remove('hidden');if(m==='pause')screens.pause.classList.remove('hidden');if(m==='end')screens.end.classList.remove('hidden');$('#mobileControls').classList.toggle('hidden',m!=='playing');$('#startHint').classList.toggle('hidden',m!=='playing'||mouseLocked);}
function renderBackdrop(t){const w=W(),h=H(),g=ctx.createLinearGradient(0,0,0,h);g.addColorStop(0,'#46504b');g.addColorStop(.38,'#858878');g.addColorStop(.53,'#4e5146');g.addColorStop(1,'#181d19');ctx.fillStyle=g;ctx.fillRect(0,0,w,h);let horizon=h*.48;
ctx.fillStyle='#353b35';for(let i=0;i<20;i++){let x=i*w/16-(t*4%90),bw=35+(i*29%64),bh=70+(i*53%200);ctx.fillRect(x,horizon-bh,bw,bh);ctx.fillStyle='#454a40';ctx.fillRect(x+5,horizon-bh+10,5,bh-12);ctx.fillStyle='#333932'}
ctx.fillStyle='#252a25';ctx.beginPath();ctx.moveTo(w*.37,horizon);ctx.lineTo(w*.44,horizon-20);ctx.lineTo(w*.54,horizon-20);ctx.lineTo(w*.65,horizon);ctx.fill();ctx.fillStyle='#515448';ctx.fillRect(0,horizon,w,h-horizon);
for(let i=0;i<80;i++){let x=(i*173+t*11)%w,y=horizon+((i*97)%Math.max(1,h-horizon));ctx.fillStyle=i%4?'#b9a87530':'#d6a86a60';ctx.fillRect(x,y,2+(i%3),1+(i%2))}
const haze=ctx.createRadialGradient(w*.69,horizon,0,w*.69,horizon,w*.32);haze.addColorStop(0,'#d58b4938');haze.addColorStop(1,'transparent');ctx.fillStyle=haze;ctx.fillRect(0,0,w,h);
}
function textureWall(x,y,side,dist,wallX,rayX,rayY){const h=H(),w=W(),lineH=Math.min(h*2,h/dist),drawY=h*.5-lineH*.5+player.pitch*h*.65;const cellX=Math.floor(wallX*8),tile=cellX%8;let shade=side?.67:1;shade*=Math.max(.35,1-dist/14);const stone=(Math.sin(Math.floor(wallX*12)*13+Math.floor(wallX*5)*7)*.045);let base=wallX<4?'#66665a':wallX<9?'#5c6257':'#636457';if(Math.floor(wallX*3)%3===0)base='#535a51';ctx.fillStyle=base;ctx.fillRect(x,drawY,2,lineH);ctx.fillStyle=`rgba(11,15,13,${1-shade+stone})`;ctx.fillRect(x,drawY,2,lineH);let row=(wallX*7)%1;
if(tile<1||tile>6){ctx.fillStyle='rgba(16,19,16,.55)';ctx.fillRect(x,drawY,2,lineH)}
// masonry seams and fractured plaster
const band=Math.floor((wallX*15)%15);if(band<1.2){ctx.fillStyle=`rgba(16,20,16,${.35+(1-shade)*.35})`;ctx.fillRect(x,drawY+lineH*.49,2,Math.max(1,lineH*.012))}
// dim industrial window bays
const wx=Math.floor(wallX*1.1), wy=Math.floor((drawY+lineH*.18)/Math.max(1,lineH*.3));if((wx*7+Math.floor(dist)*3)%9===2&&lineH>55){ctx.fillStyle='#1c2724';ctx.fillRect(x,drawY+lineH*.22,2,lineH*.18);if((wx+wy)%4===0){ctx.fillStyle='#d5a25a55';ctx.fillRect(x,drawY+lineH*.24,1,lineH*.08)}}
// near-edge warm practical light
if(Math.floor(wallX*2)%7===0&&lineH>110){ctx.fillStyle='#cf9d5a';ctx.globalAlpha=.7;ctx.fillRect(x,drawY+lineH*.68,2,Math.max(2,lineH*.018));ctx.globalAlpha=1}
}
function castWorld(){const w=W(),h=H(),horizon=h*.49+player.pitch*h*.65;let sky=ctx.createLinearGradient(0,0,0,horizon+10);sky.addColorStop(0,'#34413e');sky.addColorStop(.62,'#76796d');sky.addColorStop(1,'#bd9b6b');ctx.fillStyle=sky;ctx.fillRect(0,0,w,horizon+2);
// distant skyline silhouette
ctx.fillStyle='#343a35';for(let i=0;i<16;i++){const bx=i*w/14-(w*.04),bh=25+(i*47%85);ctx.fillRect(bx,horizon-bh,bx%3+34,bh)}
const sun=ctx.createRadialGradient(w*.74,horizon-24,1,w*.74,horizon-24,100);sun.addColorStop(0,'#f3c88555');sun.addColorStop(1,'transparent');ctx.fillStyle=sun;ctx.fillRect(w*.55,horizon-130,w*.4,160);
let floor=ctx.createLinearGradient(0,horizon,0,h);floor.addColorStop(0,'#5a594b');floor.addColorStop(.17,'#343a31');floor.addColorStop(1,'#171c19');ctx.fillStyle=floor;ctx.fillRect(0,horizon,w,h-horizon);
// perspective road seams and scattered reflections
for(let i=0;i<14;i++){let f=(i+1)/14,y=horizon+(h-horizon)*f*f;ctx.strokeStyle=`rgba(194,177,128,${.03+f*.08})`;ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}
for(let i=-9;i<=9;i++){ctx.strokeStyle='rgba(180,172,140,.035)';ctx.beginPath();ctx.moveTo(w/2+i*2,horizon);ctx.lineTo(w/2+i*w*.14,h);ctx.stroke()}
// dust in volumetric light
for(let i=0;i<32;i++){let x=(i*137+elapsed*4)%w,y=horizon+((i*97)%Math.max(1,h-horizon));ctx.fillStyle=`rgba(228,211,162,${.05+(i%4)*.025})`;ctx.fillRect(x,y,1,1)}
const dirX=Math.cos(player.angle),dirY=Math.sin(player.angle),planeX=-dirY*.66,planeY=dirX*.66;const step=Math.max(1,Math.floor(w/500)),zbuf=new Float32Array(Math.ceil(w/step)+1);
for(let sx=0,idx=0;sx<w;sx+=step,idx++){const cameraX=2*sx/w-1,rayX=dirX+planeX*cameraX,rayY=dirY+planeY*cameraX;let mx=Math.floor(player.x),my=Math.floor(player.y),ddx=Math.abs(1/(rayX||.00001)),ddy=Math.abs(1/(rayY||.00001)),stepX=rayX<0?-1:1,stepY=rayY<0?-1:1,sdx=(rayX<0?player.x-mx:mx+1-player.x)*ddx,sdy=(rayY<0?player.y-my:my+1-player.y)*ddy,side=0,guard=0;while(guard++<50){if(sdx<sdy){sdx+=ddx;mx+=stepX;side=0}else{sdy+=ddy;my+=stepY;side=1}if(map[my]?.[mx]==='#')break}let dist=side?sdy-ddy:sdx-ddx;dist=Math.max(.15,dist);zbuf[idx]=dist;const wallX=side?player.x+dist*rayX:player.y+dist*rayY;textureWall(sx,0,side,dist,wallX,rayX,rayY);if(step>1&&sx+step>w)ctx.fillRect(sx,0,w-sx,h);}
return {zbuf,step,horizon};}

